use xiom.io;

use xiom.string;
use xiom.convert;
fn cart_total(prices: [3]Str) -> Result[Float64, Str] {
  let p0 = to_float_from_str(prices[0])?;
  let p1 = to_float_from_str(prices[1])?;
  let p2 = to_float_from_str(prices[2])?;
  return Ok(p0 + p1 + p2);
}

fn main() -> Int {
  let items = ["10.00", "5.50", "2.25"];
  match cart_total(items) {
    Ok(total) => { io.println(convert.float_to_string(total)); return 200; }
    Err(e) => { io.println(e.to_str()); return 400; }
  }
}
